#include "field_qq.hpp"
int main(int argc,char**argv){fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream in(argv[1]);int nr,nc;in>>nr>>nc;vector<Row>A(nr),B;vector<int>pivs;ofstream pf(string(argv[2])+".pivots");for(auto&row:A){int n;in>>n;for(int k=0;k<n;k++){int j;in>>j;Rat x;readpoly(in,x.n);readpoly(in,x.d);x.reduce();if(!x.zero())row.emplace(j,std::move(x));}}
while(true){int best=-1,col=-1;long score=0;for(int i=0;i<nr;i++)for(auto&[j,v]:A[i]){if(fmpq_mpoly_degree_si(v.n,1,ctx)>0)continue;long z=fmpq_mpoly_length(v.n,ctx)+fmpq_mpoly_length(v.d,ctx);if(best<0||z<score){best=i;col=j;score=z;}}if(best<0)break;Row row=std::move(A[best]);Rat pivot=row[col];pf<<best<<" "<<col<<"\n";writepoly(pf,pivot.n);writepoly(pf,pivot.d);pf.flush();for(auto&[j,v]:row)v=divi(v,pivot);for(auto&other:A){auto it=other.find(col);if(it==other.end())continue;Rat factor=it->second;for(auto&[j,v]:row){Rat z=sub(other[j],mul(factor,v));if(z.zero())other.erase(j);else other[j]=std::move(z);}}pivs.push_back(col);B.push_back(std::move(row));cerr<<"rank "<<B.size()<<" terms "<<score<<" col "<<col<<'\n';}
ofstream res(string(argv[2])+".residue");int count=0;for(auto&r:A)if(!r.empty())count++;res<<count<<" "<<nc<<"\n";for(auto&r:A)if(!r.empty()){res<<r.size()<<"\n";for(auto&[j,v]:r){res<<j<<"\n";writepoly(res,v.n);writepoly(res,v.d);}}ofstream out(argv[2]);assert(out);out<<B.size()<<' '<<nc<<'\n';for(int i=0;i<int(B.size());i++){out<<pivs[i]<<' '<<B[i].size()<<'\n';for(auto&[j,v]:B[i]){out<<j<<'\n';writepoly(out,v.n);writepoly(out,v.d);}}}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
